\begin{enumerate}
\item ছাত্র-ছাত্রী, শিক্ষক, সমাজকর্মী, পুলিশ, দমকল বাহিনী, সেনাসদস্য যে কোনো লোক প্রশিক্ষণ নিয়ে রেসকিউর হতে পারে। দুর্যোগনায় কিংবা পানিতে ডুবে যার শ্বাস-হ্রাস্পদন বন্ধ হয়ে গেছে তাকে দ্রুত মুখ হতে মুখের সাহায্যে কৃত্রিমভাবে শ্বাস-প্রশ্বাস দিতে হবে। এটি অনেকটা যান্ত্রিক শ্বাস-প্রশ্বাস প্রক্রিয়ার মতোই।
\item মুখ হতে মুখের সাহায্যে কৃত্রিম শ্বাসপ্রশ্বাস
\begin{enumerate}
\item প্রথমে আহত ব্যক্তিকে পিঠের উপর ভর দিয়ে চিং করে শোয়াতে হবে এবং ঘাড় ও বুকের কাপড়গুলো খুলে ঢিলা করতে হবে।
\item আহত ব্যক্তির মুখের ভেতরে কোনো বহিরাগত বস্তু থাকলে তা আঙুল দিয়ে বের করে নিতে হবে। মুখের ভেতরের পানি বা শ্লেষ্মা থাকলে মাথা কাঁধে কাটে করে তা বের করে দিতে হবে।
\item রোগীর ঘাড়ের নিচে একটি হাত রেখে অন্য হাত দিয়ে খুতনিকে যতটুকু পারা যায় উপরের দিকে উঠিয়ে ধরতে হবে। এতে জিহ্বা যদি গলার মধ্যে আটকে থাকে তা ছুটে গিয়ে বায়ু প্রবাহের পথ উন্নত করে দিবে। অনেকসময় এ অবস্থাতেই রোগীর শ্বাস-প্রশ্বাস শুরু হয়ে যেতে পারে।
\item এরপর উদ্ধারকারীর একটি হাত রোগীর কপালের উপর রেখে ঐ হাতের বৃদ্ধাঙ্গুল ও তজনী দ্বারা রোগীর নাকের উভয় ছিদ্রকে এমনভাবে চেপে ধরতে হবে যাতে কোনো ফাঁক না থাকে।
\item এরপর রোগীর মুখে মুখ লাগিয়ে জোড়ে বাতাস দুকানোর চেষ্টা করতে হবে যেন ফুসফুসে বাতাস পৌছে যায়। তবে সরাসরি মুখে মুখ না লাগিয়ে বিশেষ মাস্ক ব্যবহার করা যেতে পারে।
\end{enumerate}
\end{enumerate}
চিত্র ৫. ১৮ মুখ হতে মুখের সাহায্যে কৃত্রিম শ্বাসপ্রশ্বাস

\section{জীববিজ্ঞান দ্বিতীয় পত্র}
\subsection{মানব শারীরিকত্ব: খ্বসন ও শ্বাসক্রিয়া}
\begin{itemize}
    \item এভাবে দুবার করার পর ঐ ব্যক্তির বুকের ওপর এক হাতের ওপর অন্য হাত রেখে দু হাতের সাহায্যে চাপ দিতে হবে। এতে হৃৎপিণ্ডের অক্সিজেনযুক্ত রক্ত দেহের গুরুত্বপূর্ণ অংশে প্রবাহিত হবে।
    \item এভাবে 15 বার চাপ দেয়ার পর আবারো দুবার মুখে লাগিয়ে ফুসফুসে বাতাস ভরে দিতে হবে।
    \item রোগীর বুকের দিকে লক্ষ রাখতে হবে। বুক উঠানামা করলে মুখ বাতাস প্রবাস করানো বন্ধ করে দিতে হবে। তা নাহলে যতক্ষণ পর্যন্ত চিকিৎসক, অক্সিজেন নল, অক্সিজেন ব্যাগ, সিলিংগার ও অ্যাস্তুলেন্স না পাওয়া যাচ্ছে ততক্ষণ পর্যন্ত এভাবে সিপিআর চালিয়ে যেতে হবে।
\end{itemize}

\section*{প্রধান শব্দভিত্তিক সারসংক্ষেপ}
\begin{itemize}
    \item \textbf{খ্বসন}: যে প্রক্রিয়ায় প্রাণী বায়ু হতে অক্সিজেন এহন করে সেই অক্সিজেনের ($\mathrm{O_{2}}$) সাহায্যে কোষাঙ্গীত সরল খাদ্যকে জারিত করে খাদ্যাঙ্গীত স্থিতিশীলকে গতিশীলতা করে এবং এতে উৎপন্ন কার্বন ডাই অক্সাইডকে ($\mathrm{CO_{2}}$) দেহ হতে বহিষ্কার করে তাকে খ্বসন বলে।
    \item \textbf{এপিগ্লাস্টিস}: মানুষের খ্বসনত্রে স্বরয়েন্দ্রের উপরে নামের তরুণাঙ্গী নির্মিত যে ছোট ঢাকনা থাকে তাকে উপজিল্কা বা এপিগ্লাস্টিস বলে। এর দ্বারা স্বরয়েন্দ্রের নির্গমন পথ নিয়ন্ত্রিত হয়।
    \item \textbf{ব্রক্ষি}: মানুষের খ্বসনত্রের ট্রাকিয়া দ্বিধা-বিভক্ত হয়ে বক্ষগহ্বরে দুটি শাখা সৃষ্টি করে। এদের ক্রোমান্লি বা ব্রক্ষি (একবচনে-bronchus) বলে। দুটি ক্রোমান্লি দুই ফুসফুসে প্রবেশ করে।
    \item \textbf{ব্রাক্ষিয়াল বুক্ষ}: প্রাইমারি ব্রক্ষাস থেকে শুরু করে অ্যালভিওলাস পর্যন্ত ফুসফুসের অভ্যন্তরীন গঠনচিত্র দেখতে অনেকটা বৃক্ষের মতো বলে একে খ্বসন বৃক্ষ বা ব্রাক্ষিয়াল বৃক্ষ বলে।
    \item \textbf{অ্যালভিওলাস}: ফুসফুসের গঠনচিত্র ও কার্যকর একটি হলো অ্যালভিওলাস। প্রতিটি অ্যালভিওলাস ক্ষুদ্র বুদ্বুদ সদৃশ বায়ুকুঠীরী বিশেষ।
    \item \textbf{শ্বাসক্রিয়া}: যে প্রক্রিয়ায় ফুসফুসে অক্সিজেন সমৃদ্ধ বায়ু প্রবেশ করে এবং কার্বন ডাই অক্সাইড সমৃদ্ধ বায়ু
\end{itemize}

